from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel
from .enums.cause10 import Cause10OrStr


class RequestCancelActivityTaskFailedEventAttributes(SdkBaseModel):
    activity_id: str = Field(alias="activityId")
    """The activityId provided in the RequestCancelActivityTask decision that failed."""

    cause: Cause10OrStr
    """The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes.
    If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it lacked sufficient permissions. For
    details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer
    Guide."""

    decision_task_completed_event_id: int = Field(alias="decisionTaskCompletedEventId")
    """The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in the
    RequestCancelActivityTask decision for this cancellation request. This information can be useful for diagnosing
    problems by tracing back the chain of events leading up to this event."""


class RequestCancelActivityTaskFailedEventAttributesDict(TypedDict):
    activity_id: str
    cause: Cause10OrStr
    decision_task_completed_event_id: int
